"""Distributions: counting, exact normalization, CDF intervals and model assumptions."""
import math
from statistics import NormalDist
import manual_solutions as author
from matrix_workings import sp,L
R=sp.Rational
def put(group,n,steps,errors,solution=None):
 author.add('PS3',f'{group:03}-{n:03}',steps,errors,'逐小问核对取值范围、归一化、分布函数端点、模型假设与独立数值计算。')
 if solution is not None:author.PATCHES[f'SRC-PS3-E{group:03}-{n:03}']['solution']=solution
def example(n,steps,errors,solution=None):
 author.add_example('PS3',n,steps,errors,'从计数或密度积分推导，核对支持范围、量纲、CDF右连续与数值概率。')
 if solution is not None:author.PATCHES['SRC-PS3-X'+n]['solution']=solution

def pmf(values,probs,label,cdf=False):
 assert len(values)==len(probs) and values==sorted(values) and len(set(values))==len(values)
 assert all(p>=0 for p in probs) and sp.simplify(sum(probs))==1
 out=[fr'**{label}。** 分布律各个可能值及概率为 $$\begin{{array}}{{c|'+('c'*len(values))+r'}x&'+'&'.join(L(x) for x in values)+r'\\\hline P(X=x)&'+'&'.join(L(p) for p in probs)+r'\end{array}.$$各概率非负，相加为1，覆盖全部可能值。']
 if cdf:
  cases=[r'0,&x<'+L(values[0])];cumulative=sp.Integer(0)
  for i in range(len(values)-1):
   cumulative+=probs[i];cases.append(L(cumulative)+r',&'+L(values[i])+r'\le x<'+L(values[i+1]))
  cases.append(r'1,&x\ge '+L(values[-1]))
  out+=[r'分布函数F(x)=P(X≤x)，逐个向左累加，得到 $$F(x)=\begin{cases}'+r'\\'.join(cases)+r'\end{cases}.$$每个跳点包含该点本身，跳跃高度等于对应概率，故右连续；负无穷处0、正无穷处1。']
 return out

def binomial(n,p,label,ks=None,full=False):
 q=1-p
 out=[f'**{label}。** 固定独立重复'+str(n)+'次，每次成功率'+L(p)+'不变，计成功次数X，所以X服从二项分布。要恰有k次成功，先选成功位置C(n,k)，每个位置模式的概率为pᵏ(1−p)ⁿ⁻ᵏ。',r'故 $$P(X=k)=\binom{'+str(n)+r'}k('+L(p)+r')^k('+L(q)+')^{'+str(n)+r'-k},\quad k=0,\ldots,'+str(n)+r'.$$其余值概率0；二项式定理使总和(p+1−p)ⁿ=1。']
 probs=[sp.binomial(n,k)*p**k*q**(n-k) for k in range(n+1)]
 if full:out+=pmf(list(range(n+1)),probs,'逐值代入')
 if ks is not None:
  result=sp.factor(sum(probs[k] for k in ks))
  out+=['所求事件包含k='+','.join(map(str,ks))+'，这些互斥取值的概率相加：$$P='+ '+'.join(r'\binom{'+str(n)+'}{'+str(k)+'}('+L(p)+')^{'+str(k)+'}('+L(q)+')^{'+str(n-k)+'}' for k in ks)+'='+L(result)+r'\approx '+format(float(result),'.9g')+'.$$']
 return out

def integrate(f,a,b,label):
 x=sp.Symbol('x');H=sp.integrate(f,x);answer=sp.simplify(sp.integrate(f,(x,a,b)))
 out=[f'**{label}。** 先把事件区间与密度非零区间相交，再积分。此处实际积分上下限为'+L(a)+'至'+L(b)+'。',r'原函数可取 $$H(x)='+L(H)+r'.$$因此 $$P=\int_{'+L(a)+'}^{'+L(b)+'}('+L(f)+r')\,dx=\left['+L(H)+r'\right]_{'+L(a)+'}^{'+L(b)+'}='+L(answer)+r'\approx '+format(float(answer),'.9g')+'.$$连续分布单点概率0，区间端点是否包含不影响此积分值。']
 return out

def normal(mu,sigma,lo,hi,label):
 assert sigma>0
 zlo=(lo-mu)/sigma if lo!=-math.inf else -math.inf;zhi=(hi-mu)/sigma if hi!=math.inf else math.inf
 Phi=lambda x:NormalDist().cdf(float(x))
 value=Phi(zhi)-Phi(zlo)
 def tex(v):return '-\\infty' if v==-math.inf else '\\infty' if v==math.inf else L(v)
 out=[f'**{label}。** 标准差σ='+L(sigma)+r'，令 $Z=(X-('+L(mu)+'))/'+L(sigma)+r'\sim N(0,1)$，上下界要同作减均值、除标准差。',r'事件化为 $$'+tex(zlo)+'<Z<'+tex(zhi)+r'.$$所以 $$P=\Phi('+tex(zhi)+r')-\Phi('+tex(zlo)+r')\approx '+format(value,'.9g')+r'.$$这里Φ(−∞)=0、Φ(+∞)=1，负数查表可用Φ(−z)=1−Φ(z)。']
 return out

